33	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
34	  private static readonly COLORS: ReadonlyArray<string> = [
35	    "#bada55",
36	    "#bada55",
37	    "#bada55",
38	    "bada55",
39	  ];
40	  private static readonly RADIUS = 3;
41	  private static readonly DOTS_PER_INTERVAL = 5;
42	  private static readonly SPAWN_INTERVAL_SEC = 0.015;
43	  private static readonly FLOOR_LEVEL = -100;
44	  private static readonly FLOOR_DIMENSIONS = 1500;
45	  /** Original gravity-balls coordinate system (~1500 unit floor) shrunk to fit rocket scale. */
46	  private static readonly INNER_SCALE_DEFAULT = 0.05;
47	  /** `?debug=1` 모드에서 점·플로어가 인터랙션·인트로에 가려지지 않게 키우는 배수. */
48	  private static readonly INNER_SCALE_DEBUG = 0.2;
49	  private static readonly DEBUG_RENDER_ORDER = 9999;
50	  private static readonly DEBUG_FLOOR_COLOR = "#ff00ff";
51	
52	  private readonly _isDebug = EnvSetup.hasQueryFlag("debug", "1");
53	
54	  private _options: Partial<GravityBallsObjectOptions> = {};
55	  private _built = false;
56	  private _innerGroup: THREE.Group | null = null;
57	  private _floor: THREE.Mesh<THREE.BoxGeometry, THREE.MeshLambertMaterial> | null =
58	    null;
59	  /** Floor의 부모 (scene root에 attach되어 외부 transform 변경에 영향받지 않음). */
60	  private _floorParent: THREE.Object3D | null = null;
61	  private _spheresInfo = new Map<number, BallInfo>();
62	  private _sphereIndex = 0;
63	  private _canvasMouse = new THREE.Vector3(0, 0, 0);
64	  private _spawnAccumulator = 0;
65	
66	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
67	    if (props != null) this._options = { ...this._options, ...props };
68	    return this;
69	  }
70	
71	  override getAnimationTarget(): THREE.Object3D | null {
72	    return this.getTimelineRoot();
73	  }
74	
75	  override getTweenApplyMode(): "mergeAndSync" {
76	    return "mergeAndSync";
77	  }
78	
79	  protected override getOptions(): Record<string, unknown> {
80	    return this._options as Record<string, unknown>;
81	  }
82	
83	  protected override applyVisibility(visible: boolean): void {
84	    const root = this.getTimelineRoot();
85	    if (!root) return;
86	    root.visible = visible;
87	    if (!visible) this._clearAllSpheres();
88	  }
89	
90	  override runObject(): void {
91	    const ctx = this._context;
92	    if (!ctx?.scene) return;
93	
94	    const root = this.ensureTimelineRoot("gravityBallsRoot");
95	    if (!root) return;
96	
97	    const attachTo = this._options.attachTo;
98	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
99	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
100	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
101	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
102	
103	    if (this._isDebug) {
104	      // 디버그: page-specific rocket 위치(예: about의 z=737)에 묻히지 않도록 씬 원점에 배치.
105	      root.position.set(0, 0, 0);
106	    } else if (attachTo && typeof ctx.getObject === "function") {
107	      const target = ctx.getObject(attachTo);
108	      if (target instanceof THREE.Object3D) {
109	        target.add(root);
110	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
111	      } else {
112	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
113	      }
114	    } else {
115	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
116	    }
117	
118	    Helpers.applyRotationDeg(root, r);
119	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
120	
121	    const inner = new THREE.Group();
122	    inner.name = "gravityBallsInner";
123	    const innerScale = this._isDebug
124	      ? GravityBalls.INNER_SCALE_DEBUG
125	      : GravityBalls.INNER_SCALE_DEFAULT;
126	    inner.scale.setScalar(innerScale);
127	    root.add(inner);
128	    this._innerGroup = inner;
129	
130	    this._buildFloor();
131	    this._built = true;
132	  }
133	
134	  override runUpdate(deltaTime: number): void {
135	    if (!this._built) return;
136	    const root = this.getTimelineRoot();
137	    if (!root) return;
138	    if (this._isDebug && !root.visible) root.visible = true;
139	    if (!root.visible) return;
140	
141	    this._spawnAccumulator += deltaTime;
142	    while (this._spawnAccumulator >= GravityBalls.SPAWN_INTERVAL_SEC) {
143	      for (let i = 0; i < GravityBalls.DOTS_PER_INTERVAL; i += 1) {
144	        this._initDot();
145	      }
146	      this._spawnAccumulator -= GravityBalls.SPAWN_INTERVAL_SEC;
147	    }
148	
149	    for (const info of Array.from(this._spheresInfo.values())) {
150	      this._drawDot(info);
151	    }
152	  }
153	
154	  override dispose(): void {
155	    this._clearAllSpheres();
156	    if (this._floor) {
157	      this._floor.geometry.dispose();
158	      this._floor.material.dispose();
159	      // Floor는 scene root에 re-parent되어 있으므로 _floorParent에서 직접 제거
160	      (this._floorParent ?? this._floor.parent)?.remove(this._floor);
161	      this._floor = null;
162	      this._floorParent = null;
163	    }
164	    if (this._innerGroup) {
165	      this._innerGroup.parent?.remove(this._innerGroup);
166	      this._innerGroup = null;
167	    }
168	    this._built = false;
169	    super.dispose();
170	  }
171	
172	  private _buildFloor(): void {
173	    const inner = this._innerGroup;
174	    const ctx = this._context;
175	    if (!inner || !ctx?.scene) return;
176	    const geometry = new THREE.BoxGeometry(
177	      GravityBalls.FLOOR_DIMENSIONS,
178	      3,
179	      GravityBalls.FLOOR_DIMENSIONS,
180	    );
181	    const material = new THREE.MeshLambertMaterial({
182	      color: this._isDebug ? GravityBalls.DEBUG_FLOOR_COLOR : "#000000",
183	      wireframe: this._isDebug,
184	    });
185	    material.depthWrite = false;
186	    material.transparent = true;
187	    material.opacity = this._isDebug ? 0.6 : 0.2;
188	    const floor = new THREE.Mesh(geometry, material);
189	    floor.position.y = GravityBalls.FLOOR_LEVEL - GravityBalls.RADIUS / 2;
190	    floor.position.z = 0;
191	    if (this._isDebug) floor.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
192	    // 1) Inner group에서 정확한 local 좌표·INNER_SCALE을 적용해 일단 부착
193	    inner.add(floor);
194	    inner.updateMatrixWorld(true);
195	    // 2) Scene root로 re-parent (world transform 보존). 이후 inner/timeline root가
196	    //    Theatre·인트로에 의해 움직여도 floor는 boot 시점 world 위치에 고정됨.
197	    ctx.scene.attach(floor);
198	    this._floor = floor;
199	    this._floorParent = ctx.scene;
200	  }
201	
202	  private _initDot(): void {
203	    const inner = this._innerGroup;
204	    if (!inner) return;
205	    const radius = GravityBalls.RADIUS;
206	    const colorIdx = this._random(0, 4);
207	    const color = GravityBalls.COLORS[colorIdx] ?? "#bada55";
208	    const radiusStart = radius;
209	    const radiusDeincrement = radius * -0.002;
210	    const startX = this._canvasMouse.x || 0;
211	    let startY = this._canvasMouse.y || 100;
212	    const startZ = this._canvasMouse.z || 0;
213	    if (startY < GravityBalls.FLOOR_LEVEL - radiusStart / 2) {
214	      startY = GravityBalls.FLOOR_LEVEL - radiusStart / 2;
215	    }
216	    const isXNegative = this._random(1, 2);
217	    const isZNegative = this._random(1, 2);
218	    const vx =
219	      isXNegative === 1
220	        ? this._random(0, 50) * -0.15
221	        : this._random(0, 50) * 0.15;
222	    const vxMult = this._random(10, 20) * 0.15;
223	    const vy = this._random(-10, 20);
224	    const vyMult = this._random(4, 6) * -0.1;
225	    const vz =
226	      isZNegative === 1
227	        ? this._random(-25, 25) * -0.4
228	        : this._random(-25, 25) * 0.4;
229	    const vzMult = this._random(10, 20) * 0.1;
230	    this._sphereIndex += 1;
231	    const ID = this._sphereIndex;
232	    const startGravity = 10;
233	    const geometry = new THREE.CircleGeometry(radius, 20);
234	    const material = new THREE.MeshBasicMaterial({
235	      color,
236	      side: THREE.DoubleSide,
237	    });
238	    if (this._isDebug) {
239	      material.depthTest = false;
240	      material.depthWrite = false;
241	      material.transparent = true;
242	    }
243	    const sphere = new THREE.Mesh(geometry, material);
244	    if (this._isDebug) sphere.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
245	    inner.add(sphere);
246	
247	    this._spheresInfo.set(ID, {
248	      color,
249	      radius,
250	      radiusStart,
251	      radiusDeincrement,
252	      startX,
253	      startY,
254	      startZ,
255	      isXNegative,
256	      isZNegative,
257	      vx,
258	      vxMult,
259	      vy,
260	      vyMult,
261	      vz,
262	      vzMult,
263	      ID,
264	      bounced: false,
265	      startGravity,
266	      gravity: startGravity,
267	      sphere,
268	    });
269	  }
270	
271	  private _drawDot(info: BallInfo): void {
272	    info.sphere.scale.x += info.radiusDeincrement;
273	    info.sphere.scale.y += info.radiusDeincrement;
274	    info.sphere.scale.z += info.radiusDeincrement;
275	    info.startX += info.vx * 0.6;
276	    info.startY -= info.vy * 0.5;
277	    info.startZ -= info.vz * 0.6;
278	    info.sphere.position.x = info.startX;
279	    info.sphere.position.y = info.startY;
280	    info.sphere.position.z = info.startZ;
281	
282	    if (
283	      info.sphere.position.y <
284	      GravityBalls.FLOOR_LEVEL - info.radiusStart / 2
285	    ) {
286	      if (!info.bounced) {
287	        info.vx *= info.vxMult;
288	        info.vz *= info.vzMult;
289	      } else {
290	        info.vx *= 0.95;
291	        info.vz *= 0.95;
292	      }
293	      const half = GravityBalls.FLOOR_DIMENSIONS / 2;
294	      const outsideFloor =
295	        info.sphere.position.x > half ||
296	        info.sphere.position.x < -half ||
297	        info.sphere.position.z > half ||
298	        info.sphere.position.z < -half;
299	      if (!outsideFloor) {
300	        info.vy *= info.vyMult;
301	        info.sphere.position.y =
302	          GravityBalls.FLOOR_LEVEL + info.radiusStart * info.sphere.scale.x;
303	      } else {
304	        info.gravity = info.startGravity / 4;
305	        info.startY -= info.vy * 0.01;
306	        info.sphere.position.y =
307	          info.startY + (20 - info.radiusStart * info.sphere.scale.x);
308	      }
309	      info.bounced = true;
310	    }
311	
312	    info.vy += info.gravity;
313	
314	    if (info.sphere.scale.y <= 0.1) {
315	      this._spheresInfo.delete(info.ID);
316	      info.sphere.parent?.remove(info.sphere);
317	      info.sphere.geometry.dispose();
318	      info.sphere.material.dispose();
319	    }
320	  }
321	
322	  private _clearAllSpheres(): void {
323	    for (const info of this._spheresInfo.values()) {
324	      info.sphere.parent?.remove(info.sphere);
325	      info.sphere.geometry.dispose();
326	      info.sphere.material.dispose();
327	    }
328	    this._spheresInfo.clear();
329	  }
330	
331	  private _random(min: number, max: number): number {
332	    return Math.floor(Math.random() * max) + min;
333	  }
334	}
