225	function createAboutObjectRegistry<TObjectId extends string>(
226	  ids: readonly TObjectId[],
227	): Record<TObjectId, true> {
228	  return ids.reduce<Record<TObjectId, true>>(
229	    (registry, id) => {
230	      registry[id] = true;
